import java.util.*;

public class Main {
    static long[][] comb;
    static char[] s;
    static int[] cnt_a, cnt_b;
    static ArrayList<Long>[] partial, partial_zero;
    static int r, c, n;

    static class Pair {
        long first, second;
        Pair(long f, long s) {
            first = f;
            second = s;
        }
    }

    static void computeComb() {
        comb = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
            }
        }
    }

    static long getDifs(int conf, int a_bef, int b_bef) {
        long ans = 0;
        for (int i = 0; i < c + 1; i++) {
            if ((conf & (1 << i)) != 0) {
                b_bef++;
                long aux1 = comb[b_bef - 1][r - 1];
                long aux2 = comb[n - b_bef][r] - comb[a_bef][r];
                ans -= aux1 * aux2;
            } else {
                a_bef++;
                long aux1 = comb[a_bef - 1][r - 1];
                long aux2 = comb[n - a_bef][r] - comb[b_bef][r];
                ans += aux1 * aux2;
            }
        }
        return ans;
    }

    static boolean check(int conf) {
        for (int i = 0; i < c + 1; i++) {
            char ch = s[2 * r + c + i];
            if (ch == 'A' && ((conf >> i) & 1) == 1) return false;
            if (ch == 'B' && ((conf >> i) & 1) == 0) return false;
        }
        return true;
    }

    static void computeSecondPart() {
        int limit = 1 << (c + 1);
        for (int conf = 0; conf < limit; conf++) {
            int b_here = Integer.bitCount(conf);
            int a_here = c + 1 - b_here;
            long val = getDifs(conf, r + c - a_here, r + c - b_here);
            if (check(conf)) {
                partial[a_here].add(val);
            } else {
                partial_zero[a_here].add(val);
            }
        }
        for (int i = 0; i <= c + 1; i++) {
            Collections.sort(partial[i]);
            Collections.sort(partial_zero[i]);
        }
    }

    static long getCoef(int conf) {
        int i, j;
        for (i = 0; i < c + 1; i++) {
            if (((conf >> i) & 1) != (conf & 1)) break;
        }
        for (j = i; j < c + 1; j++) {
            char ch = s[2 * r - 1 + j];
            if (ch == 'A' && ((conf >> j) & 1) == 1) return 0;
            if (ch == 'B' && ((conf >> j) & 1) == 0) return 0;
        }
        int set_a = r - 1 + ((conf & 1) == 0 ? i : 0);
        int set_b = r - 1 + ((conf & 1) == 1 ? i : 0);
        if (set_a < cnt_a[2 * r - 2 + i]) return 0;
        if (set_b < cnt_b[2 * r - 2 + i]) return 0;
        return comb[set_a + set_b - cnt_a[2 * r - 2 + i] - cnt_b[2 * r - 2 + i]]
                   [set_a - cnt_a[2 * r - 2 + i]];
    }

    static void upd(Pair ans, Pair act) {
        if (act.first < 0) act.first = -act.first;
        if (ans.first < act.first) return;
        if (ans.first > act.first) {
            ans.first = act.first;
            ans.second = act.second;
            return;
        }
        ans.second += act.second;
    }

    static long howMany(ArrayList<Long> data, long val) {
        int left = lowerBound(data, val);
        if (left == data.size() || data.get(left) != val) return 0;
        int right = upperBound(data, val);
        return right - left;
    }

    static int lowerBound(ArrayList<Long> data, long val) {
        int lo = 0, hi = data.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (data.get(mid) < val) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int upperBound(ArrayList<Long> data, long val) {
        int lo = 0, hi = data.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (data.get(mid) <= val) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static long computeFirstPart() {
        int limit = 1 << (c + 1);
        Pair ans = new Pair(1L << 60, 0);

        for (int conf = 0; conf < limit; conf++) {
            int b_here = Integer.bitCount(conf);
            int a_here = c + 1 - b_here;
            long act = getDifs(conf, r - 1, r - 1);

            // coef may be != 0
            long coef = getCoef(conf);
            int idx = lowerBound(partial[c + 1 - a_here], -act);
            if (idx < partial[c + 1 - a_here].size()) {
                long val = partial[c + 1 - a_here].get(idx);
                if (ans.first >= Math.abs(val + act)) {
                    long coef2 = howMany(partial[c + 1 - a_here], val);
                    upd(ans, new Pair(val + act, coef * coef2));
                }
            }
            if (idx > 0) {
                idx--;
                long val = partial[c + 1 - a_here].get(idx);
                if (ans.first >= Math.abs(val + act)) {
                    long coef2 = howMany(partial[c + 1 - a_here], val);
                    upd(ans, new Pair(val + act, coef * coef2));
                }
            }

            // coef is clearly 0
            coef = 0;
            idx = lowerBound(partial_zero[c + 1 - a_here], -act);
            if (idx < partial_zero[c + 1 - a_here].size()) {
                long val = partial_zero[c + 1 - a_here].get(idx);
                // note: original uses howMany on partial, not partial_zero
                long coef2 = howMany(partial[c + 1 - a_here], val);
                if (ans.first >= Math.abs(val + act)) {
                    upd(ans, new Pair(val + act, coef * coef2));
                }
            }
            if (idx > 0) {
                idx--;
                long val = partial_zero[c + 1 - a_here].get(idx);
                long coef2 = howMany(partial[c + 1 - a_here], val);
                if (ans.first >= Math.abs(val + act)) {
                    upd(ans, new Pair(val + act, coef * coef2));
                }
            }
        }
        return ans.second;
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        r = sc.nextInt();
        c = sc.nextInt();
        sc.nextLine(); // consume newline
        String input = sc.nextLine();
        n = 2 * (r + c);
        s = new char[n + 1];
        for (int i = 1; i <= n; i++) s[i] = input.charAt(i - 1);

        computeComb();

        cnt_a = new int[n + 1];
        cnt_b = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            cnt_a[i] = cnt_a[i - 1] + (s[i] == 'A' ? 1 : 0);
            cnt_b[i] = cnt_b[i - 1] + (s[i] == 'B' ? 1 : 0);
        }

        partial = new ArrayList[n + 1];
        partial_zero = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            partial[i] = new ArrayList<>();
            partial_zero[i] = new ArrayList<>();
        }

        computeSecondPart();
        long sol = computeFirstPart();
        System.out.println(sol);
        sc.close();
    }
}
